import sys
from collections import defaultdict, deque

def main():
    sys.setrecursionlimit(10000)
    n = int(sys.stdin.readline())
    edges = []
    adj = defaultdict(list)
    edge_map = {}
    for i in range(1, n):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))
        adj[u].append((v, i))
        adj[v].append((u, i))
        edge_map[(u, v)] = i
        edge_map[(v, u)] = i

    if n == 2:
        print(1)
        print(1, 1)
        print(1, 2, 0.5)
        return

    # Find a centroid to split the tree into paths
    def find_centroid():
        size = [0] * (n + 1)
        def dfs(u, p):
            size[u] = 1
            for v, e in adj[u]:
                if v != p:
                    dfs(v, u)
                    size[u] += size[v]
        dfs(1, -1)
        def find(u, p, total):
            for v, e in adj[u]:
                if v != p and size[v] > total // 2:
                    return find(v, u, total)
            return u
        centroid = find(1, -1, n)
        return centroid

    centroid = find_centroid()

    # BFS to find paths from centroid
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    q = deque()
    q.append(centroid)
    parent[centroid] = -1
    while q:
        u = q.popleft()
        for v, e in adj[u]:
            if parent[v] == 0 and v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                q.append(v)

    # Collect paths
    paths = []
    visited_edges = set()
    for u in range(1, n + 1):
        if parent[u] == -1:
            continue
        path_edges = []
        current = u
        while current != centroid:
            edge_idx = edge_map[(current, parent[current])]
            path_edges.append(edge_idx)
            visited_edges.add(edge_idx)
            current = parent[current]
        if path_edges:
            paths.append(path_edges)

    # For each path, choose the middle edge and place the point at 0.5
    path_info = []
    for path_edges in paths:
        if not path_edges:
            continue
        # Choose the middle edge
        mid_edge = path_edges[len(path_edges) // 2]
        # Find the edge's vertices
        for u, v in edges:
            if edge_map[(u, v)] == mid_edge:
                break
        # Place point at 0.5, moving towards v
        path_info.append((len(path_edges), path_edges, u, v, 0.5))

    # Handle the case where centroid is part of multiple paths
    # We need to ensure all vertices are covered
    # Check if centroid is covered
    centroid_covered = False
    for path_edges in paths:
        current = centroid
        for edge_idx in path_edges:
            for u, v in edges:
                if edge_map[(u, v)] == edge_idx:
                    if u == current or v == current:
                        centroid_covered = True
                        break
            if centroid_covered:
                break
        if centroid_covered:
            break

    if not centroid_covered:
        # Need to adjust paths to cover centroid
        # Find the longest path and split it
        max_path = max(paths, key=lambda x: len(x))
        if len(max_path) > 1:
            mid = len(max_path) // 2
            path1 = max_path[:mid]
            path2 = max_path[mid:]
            paths.remove(max_path)
            paths.append(path1)
            paths.append(path2)
            # Recompute path_info
            path_info = []
            for path_edges in paths:
                if not path_edges:
                    continue
                mid_edge = path_edges[len(path_edges) // 2]
                for u, v in edges:
                    if edge_map[(u, v)] == mid_edge:
                        break
                path_info.append((len(path_edges), path_edges, u, v, 0.5))

